import { defineConfig } from "astro/config";
import starlight from "@astrojs/starlight";

// The sidebar is CUJ-first: each group is one persona's set of journeys, and
// Reference is a flat lookup shelf that journeys deep-link into. Groups are
// fully autogenerated from a directory — no page is enumerated here, so adding a
// page is a file, not a config edit. Order inside a group comes from
// `sidebar.order` frontmatter, used only where sequence carries meaning.
// See docs/content_strategy/information_architecture/proposed-ia.md.
//
// The proposed IA also defines a "Build on agentevals" group (`extend/`). It is
// absent here on purpose: `autogenerate` throws on a directory with no pages, so
// the group is added in the same change as its first page.
export default defineConfig({
  site: "https://hawkeyexl.github.io",
  base: "/agentevals",
  integrations: [
    starlight({
      title: "agentevals",
      description:
        "Adherence evals for AI agent session traces. Did the session follow the skills and instructions it used?",
      social: [
        {
          icon: "github",
          label: "GitHub",
          href: "https://github.com/hawkeyexl/agentevals",
        },
      ],
      sidebar: [
        {
          label: "Get started",
          items: [{ autogenerate: { directory: "get-started" } }],
        },
        {
          label: "Declare what to check",
          items: [{ autogenerate: { directory: "declare" } }],
        },
        {
          label: "Run it in CI",
          items: [{ autogenerate: { directory: "ci" } }],
        },
        {
          label: "Trust the judge",
          items: [{ autogenerate: { directory: "judge" } }],
        },
        {
          label: "Read a failing eval",
          items: [{ autogenerate: { directory: "triage" } }],
        },
        {
          label: "Reference",
          items: [{ autogenerate: { directory: "reference" } }],
        },
      ],
    }),
  ],
});
